import {withPool,transaction,readSeeds,fail} from './shared.mjs';
const selected=key=>/^(uses|people|usecase)\./.test(key)||['nav.uses','nav.people'].includes(key)||/^spaces\.(design|repair)(Title|Text|Alt)$/.test(key)||/^campaign\.slide[1345](Title|Text|Alt)$/.test(key)||/^(hero|object|measure|spaces|tech|docs|about)\.meta(Title|Description)$/.test(key);
try{const seeds=await readSeeds();await withPool(db=>transaction(db,async client=>{let changed=0;for(const [locale,messages] of Object.entries(seeds))for(const [key,value] of Object.entries(messages)){if(!selected(key))continue;const result=await client.query(`INSERT INTO content_messages(locale,key,value) VALUES($1,$2,$3) ON CONFLICT(locale,key) DO UPDATE SET value=excluded.value,updated_at=now() WHERE content_messages.value IS DISTINCT FROM excluded.value`,[locale,key,value]);changed+=result.rowCount;}console.log(JSON.stringify({event:'usecase_content_applied',changed,scope:'Use cases, new person page, scenario captions and page SEO metadata only'}));}));}catch(error){fail(error);}
